@lru_cache(maxsize=1)
def _load_language_catalog(language):
    try:
        payload = _COMPRESSED_TRANSLATIONS[language]
    except KeyError:
        raise KeyError(language) from None
    return json.loads(zlib.decompress(base64.b85decode(payload)))

class _LazyTranslations(Mapping):
    def __getitem__(self, language):
        return _load_language_catalog(language)

    def __iter__(self):
        return iter(_COMPRESSED_TRANSLATIONS)

    def __len__(self):
        return len(_COMPRESSED_TRANSLATIONS)

TRANSLATIONS = _LazyTranslations()
